  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `code` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'Processor identifier (stripe, paypal)',
  `class_name` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'Payment processor class',
  `name` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `is_active` tinyint(1) DEFAULT '1',
