(1,	'Order Create',	'Your Order Placed #{{order_number}}',	'<p>Your Order Placed #{{order_number}}</p>\r\n<p>&nbsp;</p>\r\n<p>asdas&nbsp;</p>\r\n<p>d</p>\r\n<p>&nbsp;asf</p>\r\n<p>&nbsp;sdf</p>\r\n<p>&nbsp;sda</p>\r\n<p>f&nbsp;</p>\r\n<p>sdf</p>\r\n<p>&nbsp;sda</p>\r\n<p>f asdf</p>',	1,	'en',	NULL,	'2025-08-19 01:26:42'),
(3,	'Application Send',	'Hi {{name}} || Your Nomination is Confirmed – LoopLynks Global Recognition Initiative 2026',	'<p dir=\"ltr\">Dear {{name}},</p>\r\n<p dir=\"ltr\">Congratulations! 🎉<br><br>We are thrilled to inform you that your nomination for the LoopLynks Awards 2025 has been officially confirmed.</p>\r\n<p dir=\"ltr\">As part of the next step, we invite you to complete your award application by logging in through your unique access link.</p>\r\n<hr>\r\n<p>&nbsp;</p>\r\n<h3 dir=\"ltr\">🔗 Access Your Application Here:</h3>\r\n<p dir=\"ltr\">{{login_url}}</p>\r\n<h3 dir=\"ltr\">👤 Username: {{email}}</h3>\r\n<p dir=\"ltr\">🔒 Password: {{password}}</p>\r\n<hr>\r\n<p dir=\"ltr\"><span style=\"text-decoration: underline;\"><strong>Next Steps:<br></strong></span><br>✔ Click the link above to log into your nominee dashboard<br>✔ Complete and submit your application before the deadline<br>✔ Stay tuned for jury updates and event announcements</p>\r\n<p dir=\"ltr\">Should you face any issues or require assistance, feel free to contact our team at <strong><em>nomination@looplynks.com</em></strong></p>\r\n<p dir=\"ltr\">We&rsquo;re excited to learn more about your journey and impact.<br><br>Thank you for being part of the LoopLynks movement celebrating visionary excellence.</p>\r\n<p>{{company_signature}}</p>',	1,	'en',	'2025-08-18 05:48:19',	'2025-08-20 01:33:55'),
(4,	'User Register',	'{{company_name}}:: Welcome onboard',	'<p>Dear {{name}}</p>\r\n<p>{{company_name}} your account has been created.</p>\r\n<p>Don\'t share the credentials with any one.</p>\r\n<p>&nbsp;</p>\r\n<p>Account Details:</p>\r\n<p>Username: {{email}}</p>\r\n<p>Password: {{password}}</p>\r\n<p>&nbsp;</p>\r\n<p>Thank you for choosing us.</p>\r\n<p>&nbsp;</p>\r\n<p>{{company_signature}}</p>',	1,	'en',	'2025-08-19 00:34:15',	'2025-08-19 00:34:15'),
(5,	'User Update',	'{{company_name}}:: Account Update',	'<p>Dear {{name}}</p>\r\n<p>{{company_name}} your account has been created.</p>\r\n<p>Don\'t share the credentials with any one.</p>\r\n<p>&nbsp;</p>\r\n<p>Account Details:</p>\r\n<p>Username: {{email}}</p>\r\n<p>Password: {{password}}</p>\r\n<p>&nbsp;</p>\r\n<p>Thank you for choosing us.</p>\r\n<p>&nbsp;</p>\r\n<p>{{company_signature}}</p>',	1,	'en',	'2025-08-19 00:34:15',	'2025-08-19 00:34:15');
