(14,	'hello_world',	'utility',	'en_US',	'Hello World',	'text',	'Welcome and congratulations!! This message demonstrates your ability to send a WhatsApp message notification from the Cloud API, hosted by Meta. Thank you for taking the time to test with us.',	'WhatsApp Business Platform sample message',	NULL,	NULL,	NULL,	NULL,	NULL,	'approved',	'1736059160328795',	'{\"id\": \"1736059160328795\", \"name\": \"hello_world\", \"status\": \"APPROVED\", \"category\": \"UTILITY\", \"language\": \"en_US\", \"components\": [{\"text\": \"Hello World\", \"type\": \"HEADER\", \"format\": \"TEXT\"}, {\"text\": \"Welcome and congratulations!! This message demonstrates your ability to send a WhatsApp message notification from the Cloud API, hosted by Meta. Thank you for taking the time to test with us.\", \"type\": \"BODY\"}, {\"text\": \"WhatsApp Business Platform sample message\", \"type\": \"FOOTER\"}], \"parameter_format\": \"POSITIONAL\"}',	NULL,	'2025-08-10 23:17:31',	'2025-08-20 00:41:58'),
(22,	'award_nomination_2025',	'utility',	'en_US',	'Hi {{name}} || Your Nomination is Confirmed',	'text',	'Dear {{1}},\r\n\r\nCongratulations!\r\n\r\nWe are thrilled to inform you that your nomination for the LoopLynks Awards 2025 has been officially confirmed.\r\n\r\nAs part of the next step, we invite you to complete your award application by logging in through your unique access link.\r\n\r\nemail: {{2}}\r\npassword: {{3}}\r\n\r\nShould you face any issues or require assistance, feel free to contact our team at nomination@looplynks.com\r\n\r\nWe’re excited to learn more about your journey and impact.\r\n\r\nThank you for being part of the LoopLynks movement celebrating visionary excellence.',	'LoopLynks Team',	NULL,	NULL,	NULL,	'[\"Test\", \"test@example.com\", \"random\"]',	NULL,	'rejected',	'3641588322816547',	'{\"id\": \"3641588322816547\", \"name\": \"award_nomination_2025\", \"status\": \"REJECTED\", \"category\": \"UTILITY\", \"language\": \"en_US\", \"components\": [{\"text\": \"Hi {{name}} || Your Nomination is Confirmed\", \"type\": \"HEADER\", \"format\": \"TEXT\"}, {\"text\": \"Dear {{1}},\\r\\n\\r\\nCongratulations!\\r\\n\\r\\nWe are thrilled to inform you that your nomination for the LoopLynks Awards 2025 has been officially confirmed.\\r\\n\\r\\nAs part of the next step, we invite you to complete your award application by logging in through your unique access link.\\r\\n\\r\\nemail: {{2}}\\r\\npassword: {{3}}\\r\\n\\r\\nShould you face any issues or require assistance, feel free to contact our team at nomination@looplynks.com\\r\\n\\r\\nWe’re excited to learn more about your journey and impact.\\r\\n\\r\\nThank you for being part of the LoopLynks movement celebrating visionary excellence.\", \"type\": \"BODY\", \"example\": {\"body_text\": [[\"Test\", \"test@example.com\", \"random\"]]}}, {\"text\": \"LoopLynks Team\", \"type\": \"FOOTER\"}], \"parameter_format\": \"POSITIONAL\"}',	NULL,	'2025-08-20 00:26:43',	'2025-08-20 00:41:58'),
