(14,	'hello_world',	'utility',	'en_US',	'Hello World',	'text',	'Welcome and congratulations!! This message demonstrates your ability to send a WhatsApp message notification from the Cloud API, hosted by Meta. Thank you for taking the time to test with us.',	'WhatsApp Business Platform sample message',	NULL,	NULL,	NULL,	NULL,	NULL,	'approved',	'1736059160328795',	'{\"id\": \"1736059160328795\", \"name\": \"hello_world\", \"status\": \"APPROVED\", \"category\": \"UTILITY\", \"language\": \"en_US\", \"components\": [{\"text\": \"Hello World\", \"type\": \"HEADER\", \"format\": \"TEXT\"}, {\"text\": \"Welcome and congratulations!! This message demonstrates your ability to send a WhatsApp message notification from the Cloud API, hosted by Meta. Thank you for taking the time to test with us.\", \"type\": \"BODY\"}, {\"text\": \"WhatsApp Business Platform sample message\", \"type\": \"FOOTER\"}], \"parameter_format\": \"POSITIONAL\"}',	NULL,	'2025-08-10 23:17:31',	'2025-08-26 07:47:29'),
